class TabularQAgent(object):
    def __init__(self, num_states, num_actions, learning_rate=0.1, discount_factor=0.9):
        self.num_states = num_states
        self.num_actions = num_actions
        self.q_values = [[0.0 for _ in range(num_actions)] for _ in range(num_states)]
        self.learning_rate = learning_rate
        self.discount_factor = discount_factor

    def get_q_value(self, state, action):
        return self.q_values[state][action]

    def update_q_value(self, state, action, reward, next_state):
        max_next_q_value = max([self.q_values[next_state][a] for a in range(self.num_actions)])
        self.q_values[state][action] += self.learning_rate * (reward + self.discount_factor * max_next_q_value - self.q_values[state][action])

    def choose_action(self, state):
        return np.argmax([self.q_values[state][a] for a in range(self.num_actions)])
