def chunks(l, n):
    """Yield successive n-sized chunks from l."""
    for i in range(0, len(l), n):
        yield l[i:i + n]

class ChunkedTransform(object):
    verbose = 0
    def __init__(self, batch_size):
        self.batch_size = batch_size

    def transform(self, X):
        features = None
